380	    // Simulates runs that were killed without writing run_end — they appear active
381	    // in the file, but only the newest one can truly be running.
382	    const logs = [
383	      { filename: '20260323T100000-my-project.jsonl', is_active: true }, // old, interrupted
384	      { filename: '20260325T090000-my-project.jsonl', is_active: true }, // newest, genuinely active
385	      { filename: '20260324T120000-my-project.jsonl', is_active: true }, // middle, interrupted
